# DK FVB.  Fårup - Viborg
#
let fv = path("d3.dk.fvb");

with detail = 3, railway = :first :removed {
    # point.dk.Fårup  dk.FFH

    with link = "line.dk.FVB" {
        track(:ror :casing,
                fv[:far.yv - 0.1dl, :far.yv] << 0.5md << 1ms << 0.5mt
            ..  fv[:far.yv + 200m, :far.yv + 201m] << 1md
            ..  fv[:far.zv, :far.zv + 0.1dl]
        );
        track(fv[:far.zv, :far.zv + 1.01km]);
        line_label(:right:e, fv[:far.zv + 1km] >> 0.5mt, "FVB");
        track(fv[:far.zv + 0.99km, :rej - 0.49sw]);
    }

    with link = "point.dk.Rejstrupgård", railway = :station {
        track(fv[:rej - 0.5sw, :rej + 0.5sw]);
        marker(:left :de.hp, fv[:rej] << 0.5mt);
        slabel(:left, fv[:rej] >> 0.5mt + (-1dt, 0dt),
            "Rejstrupgård"
        );
    }

    with link = "line.dk.FVB" {
        track(fv[:rej + 0.49sw, :son - 0.49sw]);
    }

    with link = "point.dk.Sønderbæk", railway = :station {
        track(fv[:son - 0.5sw, :son + 0.5sw]);
        marker(:left :de.bf, fv[:son] << 0.5mt);
        slabel(:right, fv[:son] << 0.5mt << 1sh + (1.5dt, 2dt),
            "Sønderbæk"
        );
    }

    with link = "line.dk.FVB" {
        track(fv[:son + 0.49sw, :vil - 0.49sw]);
    }

    with link = "point.dk.Villemosegård", railway = :station {
        track(fv[:vil - 0.5sw, :vil + 0.5sw]);
        marker(:right :de.hp, fv[:vil] >> 0.5mt);
        slabel(:top, fv[:vil] >> 0.5mt >> 1sh + (-2dt, -0.3dt),
            "Villemosegård"
        );
    }

    with link = "line.dk.FVB" {
        track(fv[:vil + 0.49sw, :las - 0.49sw]);
    }

    with link = "point.dk.Læsten", railway = :station {
        track(fv[:las - 0.5sw, :las + 0.5sw]);
        marker(:left :de.hp, fv[:las] << 0.5mt);
        slabel(:bottom, fv[:las] << 0.5mt << 1sh + (0.3dt, 0.2dt),
            "Læsten"
        );
    }

    with link = "line.dk.FVB" {
        track(fv[:las + 0.49sw, :hoj - 0.49sw]);
    }

    with link = "point.dk.Højgård-MFVJ", railway = :station {
        track(fv[:hoj - 0.5sw, :hoj + 0.5sw]);
        marker(:right :de.hp, fv[:hoj] >> 0.5mt);
        slabel(:top, fv[:hoj] >> 0.5mt >> 1sh + (-2dt, -0.3dt),
            "Højgård"
        );
    }

    with link = "line.dk.FVB" {
        track(fv[:hoj + 0.49sw, :ham - 0.49sw]);
    }

    with link = "point.dk.Hammershøj", railway = :station {
        track(fv[:ham - 0.5sw, :ham + 0.5sw]);
        marker(:left :de.bf, fv[:ham] << 0.5mt);
        slabel(:bottom, fv[:ham] << 0.5mt << 1sh + (0.3dt, 0.2dt),
            "Hammershøj"
        );
    }

    with link = "line.dk.FVB" {
        track(fv[:ham + 0.49sw, :aru - 0.49sw]);
    }

    with link = "point.dk.Årupvej-MFVJ", railway = :station {
        track(fv[:aru - 0.5sw, :aru + 0.5sw]);
        marker(:right :de.hp, fv[:aru] >> 0.5mt);
        slabel(:top, fv[:aru] >> 0.5mt >> 1sh >> 0.3dt,
            "Årupvej"
        );
    }

    with link = "line.dk.FVB" {
        track(fv[:aru + 0.49sw, :kvo - 0.49sw]);
    }

    with link = "point.dk.Kvorning", railway = :station {
        track(fv[:kvo - 0.5sw, :kvo + 0.5sw]);
        marker(:left :de.hp, fv[:kvo] << 0.5mt);
        slabel(:bottom, fv[:kvo] << 0.5mt << 1sh + (3dt, 0.2dt),
            "Kvorning"
        );
    }

    with link = "line.dk.FVB" {
        track(fv[:kvo + 0.49sw, :mol - 0.49sw]);
    }

    with link = "point.dk.Mollerup", railway = :station {
        track(fv[:mol - 0.5sw, :mol + 0.5sw]);
        marker(:left :de.hp, fv[:mol] << 0.5mt);
        slabel(:bottom, fv[:mol] << 0.5mt << 1sh + (3dt, 0.2dt),
            "Mollerup"
        );
    }

    with link = "line.dk.FVB" {
        track(fv[:mol + 0.49sw, :hul - 0.49sw]);
    }

    with link = "point.dk.Hulbæk", railway = :station {
        track(fv[:hul - 0.5sw, :hul + 0.5sw]);
        marker(:right :de.hp, fv[:hul] >> 0.5mt);
        slabel(:top, fv[:hul] >> 0.5mt >> 1sh + (-1dt, -0.2dt),
            "Hulbæk"
        );
    }

    with link = "line.dk.FVB" {
        track(fv[:hul + 0.49sw, :hul + 1.21km]);
        line_label(:right:se, fv[:hul + 1.2km] >> 0.5mt, "FVB");
        track(fv[:hul + 1.19km, :oru - 0.49sw]);
    }

    with link = "point.dk.Ørum", railway = :station {
        track(fv[:oru - 0.5sw, :oru + 0.5sw]);
        marker(:left :de.bf, fv[:oru] << 0.5mt);
        slabel(:right, fv[:oru] << 0.5mt << 1sh + (1.3dt, 1.3dt),
            "Ørum"
        );
    }

    with link = "line.dk.FVB" {
        track(fv[:oru + 0.49sw, :vel - 0.49sw]);
    }

    with link = "point.dk.Velds", railway = :station {
        track(fv[:vel - 0.5sw, :vel + 0.5sw]);
        marker(:right :de.hp, fv[:vel] >> 0.5mt);
        slabel(:top, fv[:vel] >> 0.5mt >> 1sh + (-1dt, -0.4dt),
            "Velds"
        );
    }

    with link = "line.dk.FVB" {
        track(fv[:vel + 0.49sw, :fad - 0.49sw]);
    }

    with link = "point.dk.Fårdal", railway = :station {
        track(fv[:fad - 0.5sw, :fad + 0.5sw]);
        marker(:right :de.hp, fv[:fad] >> 0.5mt);
        slabel(:left, fv[:fad] >> 0.5mt >> 1sh + (-1.2dt, 1.1dt),
            "Fårdal"
        );
    }

    with link = "line.dk.FVB" {
        track(fv[:fad + 0.49sw, :vis - 0.49sw]);
    }

    with link = "point.dk.Viskum", railway = :station {
        track(fv[:vis - 0.5sw, :vis + 0.5sw]);
        marker(:left :de.hp, fv[:vis] << 0.5mt);
        slabel(:right, fv[:vis] << 0.5mt << 1sh + (1.5dt, 1.3dt),
