    with link = "line.dk.FVB" {
        track(fv[:vej + 0.49sw, :lov - 0.49sw]);
    }

    with link = "point.dk.Løvskalvejen", railway = :station {
        track(fv[:lov - 0.5sw, :lov + 0.5sw]);
        marker(:right :de.hp, fv[:lov] >> 0.5mt);
        slabel(:bottom, fv[:lov] << 0.5mt + (3dt, 0.5dt),
            "Løvskalvejen"
        );
    }

    with link = "line.dk.FVB" {
        track(fv[:lov + 0.49sw, :hau - 0.49sw]);
    }

    with link = "point.dk.Hauggaard", railway = :station {
        track(fv[:hau - 0.5sw, :hau + 0.5sw]);
        marker(:left :de.hp, fv[:hau] << 0.5mt);
        slabel(:bottom, fv[:hau] << 0.5mt << 1sh + (-1.5dt, 0.1dt),
            "Hauggaard"
        );
    }

    with link = "line.dk.FVB" {
        track(fv[:hau + 0.49sw, :tap - 0.49sw]);
    }

    with link = "point.dk.Tapdrup", railway = :station {
        track(fv[:tap - 0.5sw, :tap + 0.5sw]);
        marker(:right :de.hp, fv[:tap] >> 0.5mt);
        slabel(:top, fv[:tap] >> 0.5mt >> 1sh + (0dt, -0.4dt),
            "Tapdrup"
        );
    }

    with link = "line.dk.FVB" {
        track(fv[:tap + 0.49sw, :pra - 0.49sw]);
    }

    with link = "point.dk.Pramhuset", railway = :station {
        track(fv[:pra - 0.5sw, :pra + 0.5sw]);
        marker(:right :de.hp, fv[:pra] >> 0.5mt);
        slabel(:left, fv[:pra] >> 0.5mt >> 1sh + (-1.5dt, 0dt),
            "Pramhuset"
        );
    }

    with link = "line.dk.FVB" {
        track(fv[:pra + 0.49sw, :pra + 0.91km]);
        line_label(:left:nw, fv[:pra + 0.9km] << 0.5mt, "FVB");
        track(fv[:pra + 0.89km, :bru - 0.49sw]);
    }

    with link = "point.dk.Bruunshåb", railway = :station {
        track(fv[:bru - 0.5sw, :bru + 0.5sw]);
        marker(:left :de.hp, fv[:bru] << 0.5mt);
        slabel(:bottom, fv[:bru] << 0.5mt << 1sh << 0.2dt,
            "Bruunshåb"
        );
    }

    with link = "line.dk.FVB" {
        track(fv[:bru + 0.49sw, :sog - 0.49sw]);
    }

    with link = "point.dk.Søgårde", railway = :station {
        track(fv[:sog - 0.5sw, :sog + 0.5sw]);
        marker(:right :de.hp, fv[:sog] >> 0.5mt);
        slabel(:right, fv[:sog] >> 0.5mt >> 1sh + (-0.5dt, -1dt),
            "Søgårde"
        );
    }

    with link = "line.dk.FVB" {
        track(fv[:sog + 0.49sw, :vib.zf]);
        with layer = 1 track(:casing,
                fv[:vib.zf - 0.1dl, :vib.zf]
            ..  fv[:vib.xf, :lyn - 0.49sw] << 2ms << 2mt
        );
    }

    with link = "point.dk.Lyngvej", railway = :station {
        track(
                fv[:lyn - 0.5sw, :lyn] << 2ms << 2mt
            ..  fv[:vib.yh, :vib.yh + 0.1dl] << 2ms << 2mt
        );
        marker(:left :de.hp, fv[:lyn] << 2ms << 2.5mt);
        slabel(:left, fv[:lyn] << 2ms << 2.5mt << 1sh + (-0.8dt, 0.2dt),
            "Lyngvej"
        );
    }

    with link = "line.dk.FVB" {
        track(:ror, fv[:vib.yh, :vib - 399m] << 2ms << 2mt);
    }

    # point.dk.Viborg  dk.LST
